from review import card,save,DATE
i='TCS-3416';_,c=card(i);refs=c['references'];refs[0]['locator']='Section 1, longstanding exact queue question; Section 2, model; Section 6, Common₂ interpretation; Section 7, final question.'
refs += [dict(id='common_model',title='Nontrivial and Universal Helping for Wait-Free Queues and Stacks',authors='Hagit Attiya; Armando Castañeda; Danny Hendler',year=2015,url='https://doi.org/10.4230/LIPIcs.OPODIS.2015.31',locator='Introduction, p. 31:2: the Common₂ question as implementation from Test&Set for every n≥3; Section 2, progress and queue definitions.'),dict(id='journal2023',title='Set-Linearizable Implementations from Read/Write Operations: Sets, Fetch &Increment, Stacks and Queues with Multiplicity',authors='Armando Castañeda; Sergio Rajsbaum; Michel Raynal',year=2023,url='https://doi.org/10.1007/s00446-022-00440-y',locator='Published online 7 December 2022; Distributed Computing 36:89–106; abstract and footnote 7, exact queue question still open.'),dict(id='strong2026',title='Impossibility Results for Strong Linearizability: The Difficulty of Consistent Refereeing',authors='Hagit Attiya; Armando Castañeda; Constantin Enea',year=2026,url='https://doi.org/10.1145/3796701.3815906',pdf_url='https://arxiv.org/pdf/2506.18401v3',locator='PODC 2026; arXiv v3, 10 June 2026: Theorem 1 and Corollary 12, strongly linearizable queue impossibility.')]
save(i,dict(title='Does a wait-free exact FIFO queue belong to Common₂?',formal='For every fixed number n≥2 of asynchronous processes, is there a deterministic wait-free linearizable implementation of an initially empty, unbounded FIFO queue using only atomic read/write registers and atomic Test&Set bits? Every process may perform both Enqueue and Dequeue, repeatedly and in any order. The implementation must satisfy exact FIFO semantics in every execution, including executions with arbitrary delays and crashes. This is the source’s Common₂ question; “some objects with consensus number two” is not a free choice of base types that could include the desired queue itself.',definitions='There are n sequential processes with distinct identifiers 1,…,n. Each invokes a new high-level operation only after its previous one returns. The scheduler interleaves atomic shared-memory steps arbitrarily; a process may stop forever at any point. A register stores a finite value and supports atomic Read and Write. A Test&Set object is a bit initially 0 whose atomic operation returns the old bit and sets it to 1; arbitrarily many initially fresh objects and registers are available. Private computation and storage are allowed. No bound on memory growth or on the number of operations in a history is imposed, but every performed step manipulates finitely represented data. No Compare&Swap, stronger atomic multi-object operation, or queue base object is supplied. Sequential queue state is a finite sequence of values from {0,1}*. Enqueue(v) appends a new occurrence of v and returns an acknowledgement. Dequeue removes and returns the first occurrence if one exists; otherwise it returns a distinguished EMPTY symbol outside the value set and leaves the queue empty. Equal values may be enqueued multiple times, but each enqueue occurrence may be removed only once. Linearizability means that each finite concurrent history can be completed by responses to some pending invocations and deletion of the others, so that its completed operations have a legal sequential FIFO order preserving each process’s order and real-time order: an operation that returns before another is invoked precedes it. Wait-freedom means that any invoked operation whose process continues taking steps returns after finitely many of that process’s own steps, regardless of other processes’ speeds or failures. No promise that another process will take a step is available. The algorithm may depend on the fixed n; the question does not require one implementation for infinitely many simultaneously participating processes. Common₂ denotes types implementable for every finite n from registers and two-process-consensus power; the cited model paper states the queue question equivalently using Test&Set. Equal consensus numbers alone do not assert mutual implementability.',question_type='yes_no',answer_criterion='Construct and prove correct such a deterministic implementation for every finite n, or prove impossibility for some finite n in this model. Both exact linearizability and individual wait-free progress are required. A lock-free implementation that permits starvation, a restriction on the number of enqueuers or dequeuers, duplicated removal of an occurrence, weak-empty responses, bounded histories, or a stronger atomic base type does not meet the target. An impossibility result only for strong linearizability does not rule out ordinary linearizability.',context_blocks=[dict(title='Progress of the system is weaker than progress of every process',text='The original paper contrasts nonblocking exact queues with wait-free relaxed queues. Nonblocking progress ensures that operations keep completing somewhere in the system; wait-freedom also prevents an individual process that keeps running from being postponed forever.',citation='primary'),dict(title='The primitive basis avoids a circular formulation',text='The question concerns whether the exact queue belongs to Common₂. The earlier model paper explicitly formulates it as a wait-free queue from Test&Set for every n≥3. Naming this basis matters because the queue itself has consensus number two; allowing an arbitrary base type of that number would not state the intended implementation problem.',citation='common_model'),dict(title='Relaxed queues do not provide the exact object',text='The source allows multiplicity or weak emptiness in its relaxed variants. These changes permit weaker implementations but alter the sequential guarantees required by the present question. The later journal article’s footnote 7 still identifies the exact wait-free queue question as open.',citation='journal2023'),dict(title='A 2026 impossibility concerns a stronger consistency condition',text='Attiya, Castañeda and Enea rule out strongly linearizable queues from interfering primitives in their model, even with only lock-free progress. Strong linearizability requires a choice of linearizations that remains consistent when executions are extended. Ordinary linearizability in this card makes no such prefix-consistent-choice requirement, so that theorem does not settle Common₂ membership.',citation='strong2026')],why='Would determine whether the familiar consensus-number-two primitives suffice for an exact queue with individual progress guarantees, clarifying the limitations of the consensus hierarchy as a guide to object implementation.',references=refs,progress=[dict(date='2020',text='The source supplies relaxed queue implementations and reiterates the open exact Common₂ question for unrestricted finite process counts.',citation='primary'),dict(date='2022-12-07',text='The later journal article retains the exact queue question in footnote 7.',citation='journal2023'),dict(date='2026-07-01',text='Published strong-linearizability impossibilities establish a different consistency boundary and do not rule out an ordinary linearizable wait-free queue.',citation='strong2026')],status='source_open',status_note='Read the source’s model and Common₂ paragraph, the earlier explicit Test&Set formulation, the journal abstract and footnote 7, and the 2026 strong-linearizability theorem statements in arXiv v3. Checked later exact-queue and Common₂ searches through 12 September 2026. No general ordinary-linearizable resolution found; searches are not exhaustive.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='A longstanding test of whether consensus power characterizes implementation strength for a fundamental concurrent object. Existing score retained.',assessed_on=DATE),review_note='Recovered wait-free exact FIFO semantics and Common₂ membership, replaced the circular unrestricted base-type phrase by the source-supported Test&Set formulation, and distinguished the later strong-linearizability lower bound.',working_summary=dict(sentences=['The question asks for an exact FIFO queue shared by any fixed finite number of processes.','Every process may enqueue and dequeue, and each operation must finish in finitely many of its own steps despite other processes stopping.','Only read/write registers and Test&Set bits are supplied.','Relaxed queues and algorithms that merely guarantee system-wide progress do not meet this requirement.','The checked 2026 impossibility concerns strong linearizability, so the ordinary Common₂ question remains open in the cited sources.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','common_model','journal2023','strong2026'])),notes=['Restored exact wait-free queue and unrestricted enqueue/dequeue roles.','Specified the noncircular Test&Set/register basis using the explicit Common₂ model source.','Defined FIFO occurrences, empty responses, crashes, deterministic scheduling semantics and finite-history linearizability.','Separated wait-freedom, nonblocking progress, relaxed objects and strong linearizability; checked 2026 result.'],checked_sources=[r['url'] for r in refs])
